declare(strict_types=1);require_once __DIR__.'/../includes/task_system_operations.php';$o=getopt('',['dry-run','apply','verify','report::','backup::','db::']);$mode=isset($o['apply'])?'apply':(isset($o['verify'])?'verify':'dry-run');$db=(string)($o['db']??TaskSystemOperations::databasePath());
try{if(!is_file($db))throw new RuntimeException('Canonical database is missing.');$source=TaskSystemOperations::open($db);$audit=TaskSystemOperations::audit($source);$tables=TaskSystemOperations::tables($source);$counts=[];foreach(['users','portal_tasks','task_messages','task_events','task_attachments','task_occurrences','portal_notifications','portal_notification_status','push_subscriptions','push_deliveries'] as $t)if(in_array($t,$tables,true))$counts[$t]=TaskSystemOperations::count($source,$t);
$backup=null;if(isset($o['backup'])){$backup=TaskSystemOperations::verifyBackup((string)$o['backup']);if(!$backup['valid'])throw new RuntimeException('Specified backup did not verify.');}
